// 票卡物理编号
//TicketPhyID_t 共8个字节
//U64_t从高位到低位8个字节分别表示如下：
//1. 高位首字节: 票卡分类(ChipType_t)
//2. 如果票卡物理编号为7个字节，则：
//高位第二字节到最后一个字节（7个字节）表示为票卡高位到低位的7个字节。
//3. 如果票卡物理编号为4个字节，则：
//   1）高位起第2、3、4字节到全部填写0x00.
//   2）高位起第5、6、7、8字节到填写票卡高位到低位的4个字节。

bool_t
xdr_TicketPhyID_t (XDR *xdrs, TicketPhyID_t *objp)
{
	register int32_t *buf;

	 if (!xdr_U32_t (xdrs, &objp->TicketPhyID_t_LO))
		 return FALSE;
	 if (!xdr_U32_t (xdrs, &objp->TicketPhyID_t_HI))
		 return FALSE;
	return TRUE;
}
// 一卡通用户卡应用序列号
// 一卡通文档中记录使用16个BCD码
// 其前8个BCD数字，拆分为4个字节的HEX打印码，分别对应YKTTicketAPPID_t_HO的高位到低位的4个字节
// 其后8个BCD数字，拆分为4个字节的HEX打印码，分别对应YKTTicketAPPID_t_IO的高位到低位的4个字节
// 例如户卡应用序列号为1122334455667788则对应为：
// YKTTicketAPPID_HI为0x11223344
// YKTTicketAPPID_LO为0x55667788

bool_t
xdr_YKTTicketAPPID_t (XDR *xdrs, YKTTicketAPPID_t *objp)
{
	register int32_t *buf;

	 if (!xdr_U32_t (xdrs, &objp->YKTTicketAPPID_t_LO))
		 return FALSE;
	 if (!xdr_U32_t (xdrs, &objp->YKTTicketAPPID_t_HI))
		 return FALSE;
	return TRUE;
}
// 票卡印刷号，目前只有一票通储值票需要票卡卡面印刷号
// 按照规范的定义，暂定为“储值票卡卡面印刷号：2位厂商编码+2位产品编码+6位日期+1位批次号+5位流水号；”
// 具体内容待定

bool_t
xdr_TicketCoverPrintNumber_t (XDR *xdrs, TicketCoverPrintNumber_t *objp)
{
	register int32_t *buf;

	int i;
	 if (!xdr_vector (xdrs, (char *)objp->TicketCoverPrintNumber, 32,
		sizeof (U8_t), (xdrproc_t) xdr_U8_t))
		 return FALSE;
	return TRUE;
}
