// 票卡逻辑卡号
//使用规则
//TicketLogicalID_HI-从高位到低位依次为：前导码(U8_t)+卡印刷类型(U8_t)+批次日期(Date2_t)
//TicketLogicalID_LO-从高位到低位依次为：批次号(U8_t)+批次流水号(U16_t)+校验码(U8_t)
//其中单程票前导码1，储值票前导码6
//校验码前15位异或，异或后按10取模

bool_t
xdr_TicketLogicalID_t (XDR *xdrs, TicketLogicalID_t *objp)
{
	register int32_t *buf;

	 if (!xdr_U32_t (xdrs, &objp->TicketLogicalID_HI))
		 return FALSE;
	 if (!xdr_U32_t (xdrs, &objp->TicketLogicalID_LO))
		 return FALSE;
	return TRUE;
}
// MD5码一共16个字节，表示为MD5[0]到MD5[15]
// 在XDR文件中，使用4个的方式来定义
// MD5Tag[0]的4个字节从高位到低位分表为：存放MD5[0]、MD5[1]、MD5[2]、MD5[3]
// MD5Tag[1]的4个字节从高位到低位分表为：存放MD5[4]、MD5[5]、MD5[6]、MD5[7]
// MD5Tag[2]的4个字节从高位到低位分表为：存放MD5[8]、MD5[9]、MD5[10]、MD5[11]
// MD5Tag[3]的4个字节从高位到低位分表为：存放MD5[12]、MD5[13]、MD5[14]、MD5[15]
// 文件格式为【[原文]+16个字节的MD5】

bool_t
xdr_MD5_t (XDR *xdrs, MD5_t *objp)
{
	register int32_t *buf;

	int i;
	 if (!xdr_vector (xdrs, (char *)objp->MD5Tag, 4,
		sizeof (U32_t), (xdrproc_t) xdr_U32_t))
		 return FALSE;
	return TRUE;
}
